from __future__ import annotations

import os
from pathlib import Path
from typing import Optional, Union

import grpc
import structlog
from opentelemetry.exporter.otlp.proto.grpc.metric_exporter import OTLPMetricExporter
from opentelemetry.metrics import set_meter_provider
from opentelemetry.sdk.metrics import MeterProvider
from opentelemetry.sdk.metrics.export import PeriodicExportingMetricReader
from opentelemetry.sdk.resources import SERVICE_NAME, Resource

from rasa.shared.exceptions import RasaException
from rasa.tracing.constants import (
    ENDPOINTS_ENDPOINT_KEY,
    ENDPOINTS_INSECURE_KEY,
    ENDPOINTS_METRICS_KEY,
    ENDPOINTS_OTLP_BACKEND_TYPE,
    ENDPOINTS_ROOT_CERTIFICATES_KEY,
    ENDPOINTS_TRACING_SERVICE_NAME_KEY,
)
from rasa.tracing.metric_instrument_provider import MetricInstrumentProvider
from rasa.tracing.turn.instruments import (
    register_turn_metric_instruments,
    turn_metric_views,
)
from rasa.tracing.voice.metrics import (
    register_voice_metric_instruments,
    voice_metric_views,
)
from rasa.utils.endpoints import EndpointConfig, read_endpoint_config

TRACING_SERVICE_NAME = os.environ.get("TRACING_SERVICE_NAME", "rasa")

structlogger = structlog.get_logger()


def configure_metrics(endpoints_file: str) -> None:
    """Configure metrics export from an ``endpoints.yml`` path."""
    metrics_config = read_endpoint_config(endpoints_file, ENDPOINTS_METRICS_KEY)

    if not metrics_config:
        structlogger.debug(
            "metrics_configuration.no_metrics_config",
            event_info=(
                "The OTLP Collector has not been configured to collect "
                "metrics. Skipping."
            ),
        )
        return

    configure_metrics_from_endpoint_config(metrics_config, source=endpoints_file)


def configure_metrics_from_endpoint_config(
    metrics_config: EndpointConfig, *, source: str
) -> None:
    """Configure metrics export from an already-parsed endpoint config.

    Args:
        metrics_config: OTLP metrics settings.
        source: Human-readable origin used in log messages (e.g. file path).
    """
    if metrics_config.type != ENDPOINTS_OTLP_BACKEND_TYPE:
        structlogger.warning(
            "metrics_configuration.unknown_metrics_type",
            event_info=(
                f"Unknown metrics backend type '{metrics_config.type}' "
                f"read from '{source}', ignoring."
            ),
        )
        return

    otlp_exporter = OTLPMetricConfigurer.configure_from_endpoint_config(metrics_config)
    metric_reader = PeriodicExportingMetricReader(otlp_exporter)
    meter_provider = _create_meter_provider(metrics_config, metric_reader)
    set_meter_provider(meter_provider)

    MetricInstrumentProvider().register_instruments()
    register_voice_metric_instruments()
    register_turn_metric_instruments()


def configure_metrics_for_project(
    project_root: Union[str, Path, None] = None,
    endpoints_file: Optional[str] = None,
    is_mantle: Optional[bool] = None,
) -> None:
    """Configure metrics from ``integrations.yml`` or ``endpoints.yml``.

    Mantle contexts read only the ``metrics:`` block of ``integrations.yml``;
    *endpoints_file* is never consulted. An invalid block is logged and leaves
    metrics off instead of aborting the command. CALM contexts only read
    endpoints.

    Args:
        project_root: Project directory used to locate ``integrations.yml``.
            Defaults to the current working directory.
        endpoints_file: Path to endpoints configuration, if any. Ignored for
            Mantle contexts.
        is_mantle: Whether the CLI context is Mantle, as resolved by the caller
            (see :func:`~rasa.shared.engine_version.is_mantle_cli_context`).
            ``None`` falls back to the on-disk project layout.
    """
    from rasa.shared.project_structure import has_mantle_project_layout

    root = Path(project_root) if project_root is not None else Path.cwd()
    if is_mantle is None:
        is_mantle = has_mantle_project_layout(root)
    if is_mantle:
        _configure_metrics_from_integrations(root)
    elif endpoints_file is not None:
        configure_metrics(endpoints_file)


def _configure_metrics_from_integrations(project_root: Path) -> None:
    """Apply the ``metrics:`` block of ``integrations.yml``, if declared."""
    # Lazy import so CALM-only runs do not pull Mantle config modules.
    from rasa.mantle.config.tracing import load_integration_metrics
    from rasa.shared.project_structure import MANTLE_INTEGRATIONS_FILE

    integration_file = project_root / MANTLE_INTEGRATIONS_FILE
    try:
        settings = load_integration_metrics(project_root)
    except RasaException as error:
        structlogger.error(
            "metrics_configuration.integration_metrics_invalid",
            event_info=(
                f"Invalid 'metrics:' configuration in {integration_file}: "
                f"{error} Metrics will not be configured."
            ),
        )
        return

    if settings is None:
        return
    configure_metrics_from_endpoint_config(
        EndpointConfig.from_dict(settings.as_config_dict()),
        source=str(integration_file),
    )


def _create_meter_provider(
    config: EndpointConfig, metric_reader: PeriodicExportingMetricReader
) -> MeterProvider:
    """Create MeterProvider with service name from configuration."""
    service_name = config.kwargs.get(
        ENDPOINTS_TRACING_SERVICE_NAME_KEY, TRACING_SERVICE_NAME
    )
    return MeterProvider(
        metric_readers=[metric_reader],
        resource=Resource.create({SERVICE_NAME: service_name}),
        views=voice_metric_views() + turn_metric_views(),
    )


class OTLPMetricConfigurer:
    """The metric configurer for the OTLP Collector backend."""

    @classmethod
    def configure_from_endpoint_config(
        cls, config: EndpointConfig
    ) -> Optional[OTLPMetricExporter]:
        """Configure metrics for OTLP Collector."""
        insecure = config.kwargs.get(ENDPOINTS_INSECURE_KEY)
        credentials = _get_credentials(config, insecure)

        otlp_metric_exporter = OTLPMetricExporter(
            endpoint=config.kwargs[ENDPOINTS_ENDPOINT_KEY],
            insecure=insecure,
            credentials=credentials,
        )
        structlogger.info(
            "metrics_configuration.otlp_collector_config_configured",
            event_info=(
                f"Registered '{config.type}' endpoint for metrics. "
                f"Metrics will be exported to {config.kwargs[ENDPOINTS_ENDPOINT_KEY]}."
            ),
        )

        return otlp_metric_exporter


def _get_credentials(
    config: EndpointConfig, insecure: Optional[bool]
) -> Optional[grpc.ChannelCredentials]:
    """Get gRPC credentials from configuration."""
    credentials = None
    if not insecure and ENDPOINTS_ROOT_CERTIFICATES_KEY in config.kwargs:
        with open(config.kwargs.get(ENDPOINTS_ROOT_CERTIFICATES_KEY), "rb") as f:
            root_cert = f.read()
        credentials = grpc.ssl_channel_credentials(root_certificates=root_cert)
    return credentials
